package cc.clancollective.plugin;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(CollectiveConfig.GROUP)
public interface CollectiveConfig extends Config
{
	String GROUP = "clancollective";
	String CLANS = "clans";
	String WARNING = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers";

	@ConfigItem(
		keyName = "bingo",
		name = "Clan bingo",
		description = "While your clan runs a bingo on Clan Collective (clancollective.cc) and you are on a team, "
			+ "drops, collection log slots, pets, XP, levels, kill counts, kill times and clues that match an open tile "
			+ "are sent there. Sends your clan name, RSN, a one-way hash of your account and the matching names and amounts.",
		warning = WARNING,
		position = 0
	)
	default boolean bingo()
	{
		return false;
	}

	@ConfigItem(
		keyName = "bingoScreenshots",
		name = "Bingo screenshots",
		description = "Attach a screenshot of your game when something ticks a bingo tile, so captains can check it. "
			+ "Kill counts and XP only on the kill or gain that finishes the tile. Chat is hidden.",
		warning = WARNING,
		position = 1
	)
	default boolean bingoScreenshots()
	{
		return false;
	}

	@ConfigItem(
		keyName = CLANS,
		name = "Clan listings",
		description = "Show your clan's Clan Collective (clancollective.cc) listing in the side panel, "
			+ "or clans to browse when you are not in one. Sends your clan name.",
		warning = WARNING,
		position = 2
	)
	default boolean clans()
	{
		return false;
	}
}

package cc.clancollective.plugin;

import cc.clancollective.plugin.bingo.BingoCapture;
import cc.clancollective.plugin.bingo.BingoChat;
import cc.clancollective.plugin.bingo.BingoService;
import cc.clancollective.plugin.clan.ClanService;
import cc.clancollective.plugin.ui.BingoPanel;
import cc.clancollective.plugin.ui.ClanPanel;
import com.google.inject.Provides;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ClanChannelChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Collective",
	description = "Clan bingo and clan listings from Clan Collective",
	tags = {"clan", "bingo", "event", "competition", "directory"}
)
public class CollectivePlugin extends Plugin
{
	private static final int CHECK_TICKS = 10;
	private static final int PAIR_TICKS = 5;
	private static final String CLOG_PREFIX = "New item added to your collection log: ";
	private static final String[] PET_MESSAGES = {
		"You have a funny feeling like you're being followed",
		"You feel something weird sneaking into your backpack",
		"You have a funny feeling like you would have been followed",
	};

	@Inject
	private Client client;
	@Inject
	private ChatMessageManager chatMessageManager;
	@Inject
	private CollectiveConfig config;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private ItemManager itemManager;
	@Inject
	private BingoService bingoService;
	@Inject
	private ClanService clanService;
	@Inject
	private BingoCapture capture;

	private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
	private final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
	private BingoPanel panel;
	private ClanPanel clanPanel;
	private NavigationButton navButton;
	private int ticks;
	private String kcName;
	private int kcTick = Integer.MIN_VALUE / 2;
	private int bestSeconds;
	private int secondsTick = Integer.MIN_VALUE / 2;
	private String lastClan;
	private String lastRsn;
	private long lastHash = -1;

	@Override
	protected void startUp()
	{
		clanPanel = new ClanPanel(clanService);
		panel = new BingoPanel(bingoService, itemManager, clanPanel, () -> bingoService.refreshIfOlderThan(60_000L));
		bingoService.onChange(this::redraw);
		navButton = NavigationButton.builder().tooltip("Collective").priority(7).panel(panel)
			.icon(ImageUtil.loadImageResource(BingoPanel.class, BingoPanel.ICON)).build();
		clientToolbar.addNavigation(navButton);
		redraw();
		showClan();
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		flushXp(true);
		xp.clear();
		levels.clear();
		bingoService.onChange(() -> { });
		bingoService.reset();
		clanPanel.stop();
		clanPanel = null;
		panel = null;
		navButton = null;
		ticks = 0;
		kcName = null;
		bestSeconds = 0;
		lastClan = null;
		lastRsn = null;
		lastHash = -1;
	}

	@Provides
	CollectiveConfig provideConfig(final ConfigManager configManager)
	{
		return configManager.getConfig(CollectiveConfig.class);
	}

	@Subscribe
	public void onConfigChanged(final ConfigChanged event)
	{
		if (!CollectiveConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (CollectiveConfig.CLANS.equals(event.getKey()))
		{
			showClan();
		}
		if (config.bingo())
		{
			redraw();
		}
		else
		{
			bingoService.reset();
		}
	}

	@Subscribe
	public void onGameTick(final GameTick event)
	{
		if (config.bingo() && ++ticks >= CHECK_TICKS)
		{
			ticks = 0;
			lastClan = clanName();
			lastRsn = localRsn();
			lastHash = client.getAccountHash();
			bingoService.refresh(lastClan, lastRsn, lastHash);
			flushXp(false);
		}
	}

	@Subscribe
	public void onStatChanged(final StatChanged event)
	{
		final Integer before = xp.put(event.getSkill(), event.getXp());
		final Integer levelBefore = levels.put(event.getSkill(), event.getLevel());
		if (config.bingo() && before != null)
		{
			if (bingoService.addXp(event.getSkill().getName(), event.getXp() - before))
			{
				send(BingoService.XP, bingoService.takeXp(true), config.bingoScreenshots());
			}
			if (event.getLevel() > levelBefore)
			{
				submit(BingoService.LEVEL, Collections.singletonMap(event.getSkill().getName(), event.getLevel()));
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(final GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			flushXp(true);
			xp.clear();
			levels.clear();
			showClan();
		}
	}

	@Subscribe
	public void onClanChannelChanged(final ClanChannelChanged event)
	{
		if (!event.isGuest())
		{
			showClan();
		}
	}

	@Subscribe
	public void onChatMessage(final ChatMessage event)
	{
		if (!config.bingo() || event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		final String message = Text.removeTags(event.getMessage());
		if (message.startsWith(CLOG_PREFIX))
		{
			submit(BingoService.CLOG, Collections.singletonMap(message.substring(CLOG_PREFIX.length()).trim(), 1));
			return;
		}
		for (final String pet : PET_MESSAGES)
		{
			if (message.startsWith(pet))
			{
				submit(BingoService.PET, Collections.emptyMap());
				return;
			}
		}
		final int tick = client.getTickCount();
		final String boss = BingoChat.killCount(message);
		final int seconds = boss == null ? BingoChat.seconds(message) : -1;
		if (boss != null)
		{
			submit(BingoService.KC, Collections.singletonMap(boss, 1));
			kcName = boss;
			kcTick = tick;
		}
		else if (seconds > 0)
		{
			bestSeconds = tick - secondsTick > PAIR_TICKS ? seconds : Math.max(bestSeconds, seconds);
			secondsTick = tick;
		}
		else
		{
			final String tier = BingoChat.clueTier(message);
			if (tier != null)
			{
				submit(BingoService.CLUE, Collections.singletonMap(tier, 1));
			}
			return;
		}
		if (kcName != null && bestSeconds > 0 && Math.abs(kcTick - secondsTick) <= PAIR_TICKS)
		{
			submit(BingoService.PB, Collections.singletonMap(kcName, bestSeconds));
			kcName = null;
			bestSeconds = 0;
		}
	}

	@Subscribe
	public void onLootReceived(final LootReceived event)
	{
		if (config.bingo())
		{
			final Map<String, Integer> items = new LinkedHashMap<>();
			for (final ItemStack stack : event.getItems())
			{
				items.merge(itemManager.getItemComposition(stack.getId()).getName(), stack.getQuantity(), Integer::sum);
			}
			submit(BingoService.DROP, items);
		}
	}

	private void submit(final String kind, final Map<String, Integer> items)
	{
		final Map<String, Integer> matched = bingoService.matching(kind, items);
		send(kind, matched, config.bingoScreenshots() && (!BingoService.KC.equals(kind) || bingoService.completes(kind, matched)));
	}

	private void send(final String kind, final Map<String, Integer> matched, final boolean screenshot)
	{
		final String clan = clanName();
		final String rsn = localRsn();
		final long hash = client.getAccountHash();
		if (matched.isEmpty() || clan == null || rsn == null)
		{
			return;
		}
		if (!screenshot)
		{
			bingoService.submit(clan, rsn, hash, kind, matched, null, this::announce);
			return;
		}
		capture.take(shot -> bingoService.submit(clan, rsn, hash, kind, matched, shot, this::announce));
	}

	private void flushXp(final boolean force)
	{
		if (lastClan != null && lastRsn != null && lastHash != -1)
		{
			bingoService.submit(lastClan, lastRsn, lastHash, BingoService.XP, bingoService.takeXp(force), null, this::announce);
		}
	}

	private void redraw()
	{
		final BingoPanel p = panel;
		if (p != null)
		{
			p.show(bingoService.board(), config.bingo());
		}
	}

	private void showClan()
	{
		final BingoPanel p = panel;
		if (p != null)
		{
			p.clan(loggedInClan(), config.clans());
		}
	}

	private String loggedInClan()
	{
		return client.getGameState().getState() >= GameState.LOADING.getState() ? clanName() : null;
	}

	private void announce(final String message)
	{
		chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(new ChatMessageBuilder().append(ChatColorType.HIGHLIGHT).append("[Bingo] ")
				.append(ChatColorType.NORMAL).append(message).build()).build());
	}

	private String clanName()
	{
		final ClanChannel channel = client.getClanChannel();
		return channel != null ? channel.getName() : null;
	}

	private String localRsn()
	{
		final Player local = client.getLocalPlayer();
		return local != null && local.getName() != null ? Text.toJagexName(local.getName()) : null;
	}
}

package cc.clancollective.plugin.bingo;

import java.util.Collections;
import java.util.List;
import lombok.Getter;

@Getter
public class BingoBoard
{
	private String event;
	private String team;
	private int size;
	private String color;
	private int points;
	private int done;
	private int lines;
	private int total;
	private int rank;
	private int teams;
	private boolean hidden;
	private int picks;
	private String url;
	private List<Tile> tiles = Collections.emptyList();
	private List<Unlock> unlocks = Collections.emptyList();

	BingoBoard named(final String event, final String team)
	{
		this.event = event;
		this.team = team;
		return this;
	}

	@Getter
	public static class Tile
	{
		private int pos;
		private String name;
		private String kind;
		private String icon;
		private String img;
		private List<String> items = Collections.emptyList();
		private int points;
		private int target;
		private int progress;
		private String status;
		private boolean mine;

		public boolean isDone()
		{
			return "done".equals(status);
		}

		public boolean isReview()
		{
			return "review".equals(status);
		}

		public boolean isLocked()
		{
			return "locked".equals(status);
		}

		void update(final int progress, final String status)
		{
			this.progress = progress;
			this.status = status;
		}
	}

	@Getter
	public static class Unlock
	{
		private String tile;
		private String at;
		private List<String> by = Collections.emptyList();
	}
}

package cc.clancollective.plugin.bingo;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.ImageUtil;

@Singleton
public class BingoCapture
{
	private static final int[] CHAT = {InterfaceID.Chatbox.CHATAREA, InterfaceID.PmChat.CONTAINER};

	private final Client client;
	private final ClientThread clientThread;
	private final DrawManager drawManager;
	private final ScheduledExecutorService executor;

	@Inject
	BingoCapture(final Client client, final ClientThread clientThread, final DrawManager drawManager,
		final ScheduledExecutorService executor)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.drawManager = drawManager;
		this.executor = executor;
	}

	public void take(final Consumer<byte[]> done)
	{
		final List<Widget> hidden = hideChat();
		drawManager.requestNextFrameListener(frame ->
		{
			final BufferedImage image = ImageUtil.bufferedImageFromImage(frame);
			clientThread.invokeLater(() -> hidden.forEach(w -> w.setHidden(false)));
			executor.execute(() -> done.accept(jpeg(image)));
		});
	}

	private List<Widget> hideChat()
	{
		final List<Widget> hidden = new ArrayList<>();
		for (final int id : CHAT)
		{
			final Widget widget = client.getWidget(id);
			if (widget != null && !widget.isSelfHidden())
			{
				widget.setHidden(true);
				hidden.add(widget);
			}
		}
		return hidden;
	}

	static byte[] jpeg(final BufferedImage image)
	{
		final BufferedImage rgb = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_RGB);
		final Graphics2D g = rgb.createGraphics();
		g.drawImage(image, 0, 0, null);
		g.dispose();
		try (ByteArrayOutputStream out = new ByteArrayOutputStream())
		{
			return ImageIO.write(rgb, "jpg", out) ? out.toByteArray() : null;
		}
		catch (IOException e)
		{
			return null;
		}
	}
}

package cc.clancollective.plugin.bingo;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public final class BingoChat
{
	private static final Pattern KILL_COUNT = Pattern.compile(
		"^Your (?:completion count for |subdued |completed )?(.+?) (?:(?:kill|harvest|lap|completion|chest|success) )?(?:count )?is: ?[0-9,]+");
	private static final Pattern RIFTS = Pattern.compile("^Amount of rifts you have closed: ?[0-9,]+");
	private static final Pattern DURATION = Pattern.compile(
		"(?:duration|completion time): ?([0-9]+(?::[0-9]{1,2}){1,2}(?:\\.[0-9]+)?)", Pattern.CASE_INSENSITIVE);
	private static final Pattern CLUE = Pattern.compile(
		"^You have completed [0-9,]+ (beginner|easy|medium|hard|elite|master) Treasure Trails?", Pattern.CASE_INSENSITIVE);

	private BingoChat()
	{
	}

	public static String killCount(final String message)
	{
		if (RIFTS.matcher(message).find())
		{
			return "Guardians of the Rift";
		}
		final Matcher m = KILL_COUNT.matcher(message);
		return m.find() ? m.group(1).trim() : null;
	}

	public static int seconds(final String message)
	{
		final Matcher m = DURATION.matcher(message);
		if (!m.find())
		{
			return -1;
		}
		double total = 0;
		for (final String part : m.group(1).split(":"))
		{
			total = total * 60 + Double.parseDouble(part);
		}
		return (int) Math.round(total);
	}

	public static String clueTier(final String message)
	{
		final Matcher m = CLUE.matcher(message);
		if (!m.find())
		{
			return null;
		}
		final String tier = m.group(1).toLowerCase(Locale.ROOT);
		return Character.toUpperCase(tier.charAt(0)) + tier.substring(1);
	}
}

package cc.clancollective.plugin.bingo;

import cc.clancollective.plugin.net.CollectiveApi;
import com.google.common.collect.ImmutableMap;
import com.google.common.hash.Hashing;
import com.google.gson.Gson;
import java.awt.image.BufferedImage;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;

@Singleton
public class BingoService
{
	public static final String DROP = "drop";
	public static final String CLOG = "clog";
	public static final String PET = "pet";
	public static final String XP = "xp";
	public static final String LEVEL = "level";
	public static final String KC = "kc";
	public static final String PB = "pb";
	public static final String CLUE = "clue";

	private static final long REFRESH_MS = 900_000L;
	private static final long ERROR_RETRY_MS = 300_000L;
	private static final long BATCH_MS = 300_000L;

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final Object lock = new Object();
	private final Map<String, Integer> pendingXp = new LinkedHashMap<>();
	private final Map<String, BufferedImage> images = new ConcurrentHashMap<>();
	private String key;
	private Watch watch = Watch.NONE;
	private long nextAllowedMs;
	private long fetchedMs;
	private long batchSentMs;
	private boolean inFlight;
	private volatile Runnable onChange = () -> { };

	@Inject
	public BingoService(final OkHttpClient runeliteClient, final Gson gson)
	{
		this.gson = gson;
		this.httpClient = CollectiveApi.client(runeliteClient);
	}

	public void refresh(final String clan, final String rsn, final long accountHash)
	{
		if (clan == null || clan.isEmpty() || rsn == null || rsn.isEmpty())
		{
			return;
		}
		final String lookup = (clan + "|" + rsn).toLowerCase(Locale.ROOT);
		synchronized (lock)
		{
			if (!lookup.equals(key))
			{
				key = lookup;
				watch = Watch.NONE;
				nextAllowedMs = 0L;
			}
			if (inFlight || System.currentTimeMillis() < nextAllowedMs)
			{
				return;
			}
			inFlight = true;
		}
		final Request.Builder request = CollectiveApi.request(CollectiveApi.url("api/bingo/watch")
			.addQueryParameter("cc", clan).addQueryParameter("rsn", rsn).build()).get();
		if (accountHash != -1)
		{
			request.header("X-Collective-Account", scramble(accountHash));
		}
		CollectiveApi.send(httpClient, gson, request.build(), Watch.class, result -> finish(lookup, result));
	}

	public void reset()
	{
		synchronized (lock)
		{
			key = null;
			watch = Watch.NONE;
			nextAllowedMs = 0L;
			pendingXp.clear();
		}
		onChange.run();
	}

	public void onChange(final Runnable listener)
	{
		onChange = listener;
	}

	public BingoBoard board()
	{
		synchronized (lock)
		{
			return watch.active && watch.board != null ? watch.board.named(watch.event, watch.team) : null;
		}
	}

	public void refreshIfOlderThan(final long ageMs)
	{
		synchronized (lock)
		{
			if (System.currentTimeMillis() - fetchedMs > ageMs)
			{
				nextAllowedMs = 0L;
			}
		}
	}

	public boolean wants(final String kind, final String name)
	{
		synchronized (lock)
		{
			return watch.wants(kind, name);
		}
	}

	public boolean addXp(final String skill, final int gained)
	{
		if (gained <= 0 || !wants(XP, skill))
		{
			return false;
		}
		synchronized (lock)
		{
			final int total = pendingXp.merge(skill, gained, Integer::sum);
			return watch.completes(XP, Collections.singletonMap(skill, total), false);
		}
	}

	public Map<String, Integer> takeXp(final boolean force)
	{
		synchronized (lock)
		{
			final long now = System.currentTimeMillis();
			if (pendingXp.isEmpty() || !force && now - batchSentMs < BATCH_MS)
			{
				return Collections.emptyMap();
			}
			batchSentMs = now;
			final Map<String, Integer> out = new LinkedHashMap<>(pendingXp);
			pendingXp.clear();
			return out;
		}
	}

	public Map<String, Integer> matching(final String kind, final Map<String, Integer> items)
	{
		if (PET.equals(kind))
		{
			return wants(PET, "") ? Collections.singletonMap("", 1) : Collections.emptyMap();
		}
		final Map<String, Integer> out = new LinkedHashMap<>();
		items.forEach((name, qty) -> out.computeIfAbsent(name, n -> wants(kind, n) ? qty : null));
		return out;
	}

	public void submit(final String clan, final String rsn, final long accountHash, final String kind,
		final Map<String, Integer> matched, final byte[] screenshot, final Consumer<String> onClaim)
	{
		if (clan == null || rsn == null || accountHash == -1 || matched.isEmpty())
		{
			return;
		}
		final String json = gson.toJson(ImmutableMap.of("cc", clan, "rsn", rsn, "accountHash", scramble(accountHash),
			"kind", kind, "items", matched.entrySet().stream().filter(e -> !e.getKey().isEmpty())
				.map(e -> ImmutableMap.of("name", e.getKey(), "qty", e.getValue())).collect(Collectors.toList())));
		final RequestBody body = screenshot == null ? RequestBody.create(MediaType.parse("application/json"), json)
			: new MultipartBody.Builder().setType(MultipartBody.FORM).addFormDataPart("payload_json", json)
				.addFormDataPart("file", "bingo.jpg", RequestBody.create(MediaType.parse("image/jpeg"), screenshot)).build();
		final boolean quiet = XP.equals(kind) || KC.equals(kind) || CLUE.equals(kind);
		CollectiveApi.send(httpClient, gson, CollectiveApi.request(CollectiveApi.url("api/bingo/event").build())
			.post(body).build(), Claims.class, claims ->
		{
			final List<Claims.Tile> tiles = claims == null || claims.tiles == null ? Collections.emptyList() : claims.tiles;
			synchronized (lock)
			{
				watch.update(tiles);
			}
			if (!tiles.isEmpty())
			{
				onChange.run();
			}
			for (final Claims.Tile t : tiles)
			{
				final boolean open = "open".equals(t.status);
				if (!open || !quiet)
				{
					onClaim.accept(t.message());
				}
				if (!open)
				{
					refreshIfOlderThan(-1);
				}
			}
		});
	}

	public boolean completes(final String kind, final Map<String, Integer> matched)
	{
		synchronized (lock)
		{
			return watch.completes(kind, matched, true);
		}
	}

	public void image(final String path, final Consumer<BufferedImage> done)
	{
		final HttpUrl url = CollectiveApi.image(path);
		final BufferedImage hit = url == null ? null : images.get(path);
		if (url == null || hit != null)
		{
			done.accept(hit);
			return;
		}
		CollectiveApi.fetchImage(httpClient, url, image ->
		{
			if (image != null)
			{
				images.put(path, image);
			}
			done.accept(image);
		});
	}

	static String scramble(final long accountHash)
	{
		return Hashing.sha256().hashString("clancollective-bingo:" + accountHash, StandardCharsets.UTF_8).toString().substring(0, 32);
	}

	private void finish(final String lookup, final Watch result)
	{
		synchronized (lock)
		{
			inFlight = false;
			if (!lookup.equals(key))
			{
				return;
			}
			fetchedMs = System.currentTimeMillis();
			nextAllowedMs = fetchedMs + (result == null ? ERROR_RETRY_MS : REFRESH_MS);
			watch = result == null ? Watch.NONE : result.normalised();
		}
		onChange.run();
	}

	static final class Watch
	{
		static final Watch NONE = new Watch();

		boolean active;
		String event;
		String team;
		BingoBoard board;
		List<String> drop;
		List<String> clog;
		List<String> xp;
		List<String> level;
		List<String> kc;
		List<String> pb;
		List<String> clue;
		boolean pet;
		private transient Map<String, Set<String>> names = Collections.emptyMap();

		Watch normalised()
		{
			names = new ImmutableMap.Builder<String, Set<String>>().put(DROP, lower(drop)).put(CLOG, lower(clog))
				.put(XP, lower(xp)).put(LEVEL, lower(level)).put(KC, lower(kc)).put(PB, lower(pb)).put(CLUE, lower(clue)).build();
			return this;
		}

		boolean wants(final String kind, final String name)
		{
			if (!active)
			{
				return false;
			}
			if (PET.equals(kind))
			{
				return pet;
			}
			return names.getOrDefault(kind, Collections.emptySet()).contains(key(kind, name));
		}

		boolean completes(final String kind, final Map<String, Integer> matched, final boolean whenUnknown)
		{
			boolean found = false;
			for (final Map.Entry<String, Integer> e : matched.entrySet())
			{
				final String key = key(kind, e.getKey());
				for (final BingoBoard.Tile t : board == null ? Collections.<BingoBoard.Tile>emptyList() : board.getTiles())
				{
					if (kind.equals(t.getKind()) && !t.isDone() && !t.isReview()
						&& t.getItems().stream().anyMatch(i -> key(kind, i).equals(key)))
					{
						found = true;
						if (t.getProgress() + e.getValue() >= t.getTarget())
						{
							return true;
						}
					}
				}
			}
			return !found && whenUnknown;
		}

		private static String key(final String kind, final String name)
		{
			final String n = name == null ? "" : name.toLowerCase(Locale.ROOT);
			return KC.equals(kind) || PB.equals(kind) ? bossKey(n) : n;
		}

		void update(final List<Claims.Tile> claims)
		{
			for (final Claims.Tile c : board == null ? Collections.<Claims.Tile>emptyList() : claims)
			{
				board.getTiles().stream().filter(t -> t.getName().equals(c.tile)).forEach(t -> t.update(c.progress, c.status));
			}
		}

		static String bossKey(final String name)
		{
			final String key = name.replace('\u2019', '\'').split(":")[0].trim();
			return key.startsWith("the ") ? key.substring(4) : key;
		}

		private static Set<String> lower(final List<String> names)
		{
			return names == null ? Collections.emptySet()
				: names.stream().map(n -> n.toLowerCase(Locale.ROOT)).collect(Collectors.toSet());
		}
	}

	static final class Claims
	{
		List<Tile> tiles;

		static final class Tile
		{
			String tile;
			String status;
			int progress;
			int target;

			String message()
			{
				return tile + ("done".equals(status) ? " done!" : "review".equals(status) ? " sent for review." : " " + progress + "/" + target);
			}
		}
	}
}

package cc.clancollective.plugin.clan;

import cc.clancollective.plugin.net.CollectiveApi;
import com.google.gson.Gson;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.client.util.ImageUtil;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;

@Singleton
public class ClanService
{
	public static final int AVATAR = 32;
	private static final int MAX_AVATARS = 200;

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final Map<String, BufferedImage> avatars = Collections.synchronizedMap(new LinkedHashMap<String, BufferedImage>(64, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(final Map.Entry<String, BufferedImage> eldest)
		{
			return size() > MAX_AVATARS;
		}
	});

	@Inject
	public ClanService(final OkHttpClient runeliteClient, final Gson gson)
	{
		this.httpClient = CollectiveApi.client(runeliteClient);
		this.gson = gson;
	}

	public void mine(final String clan, final Consumer<Mine> done)
	{
		get(CollectiveApi.url("api/clan/stats").addQueryParameter("cc", clan).build(), Mine.class, true, done);
	}

	public void directory(final String type, final Consumer<List<Clan>> done)
	{
		final HttpUrl.Builder url = CollectiveApi.url("api/clans").addQueryParameter("game", "osrs").addQueryParameter("limit", "50");
		if (type != null)
		{
			url.addQueryParameter("type", type);
		}
		get(url.build(), Directory.class, false, d -> done.accept(d == null ? null : d.clans));
	}

	public void avatar(final String path, final Consumer<BufferedImage> done)
	{
		final HttpUrl url = CollectiveApi.image(path);
		final BufferedImage hit = url == null ? null : avatars.get(path);
		if (url == null || hit != null)
		{
			done.accept(hit);
			return;
		}
		CollectiveApi.fetchImage(httpClient, url, image ->
		{
			final BufferedImage small = image == null ? null : ImageUtil.resizeImage(image, AVATAR, AVATAR);
			if (small != null)
			{
				avatars.put(path, small);
			}
			done.accept(small);
		});
	}

	private <T> void get(final HttpUrl url, final Class<T> type, final boolean readNotFound, final Consumer<T> done)
	{
		CollectiveApi.send(httpClient, gson, CollectiveApi.request(url).get().build(), type, readNotFound, done);
	}

	@Getter
	public static class Clan
	{
		private String name;
		private String slug;
		private String blurb;
		private String avatar;
		private List<String> types;
		private int members;

		public List<String> getTypes()
		{
			return types == null ? Collections.emptyList() : types;
		}
	}

	@Getter
	public static class Mine
	{
		private Clan card;
		private Double ehp;
		private Double ehb;
	}

	private static class Directory
	{
		private List<Clan> clans;
	}
}

package cc.clancollective.plugin.net;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.function.Consumer;
import javax.imageio.ImageIO;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

@Slf4j
public final class CollectiveApi
{
	public static final HttpUrl BASE_URL = HttpUrl.get("https://clancollective.cc");
	private static final String IMAGES = "/static/img/";
	private static final String THUMBS = "/img/";

	private CollectiveApi()
	{
	}

	public static OkHttpClient client(final OkHttpClient runeliteClient)
	{
		return runeliteClient.newBuilder().followRedirects(false).followSslRedirects(false).build();
	}

	public static HttpUrl.Builder url(final String path)
	{
		return BASE_URL.newBuilder().addPathSegments(path);
	}

	public static HttpUrl image(final String path)
	{
		if (path == null || !(path.startsWith(IMAGES) || path.startsWith(THUMBS) && path.endsWith(".png")) || path.contains(".."))
		{
			return null;
		}
		final HttpUrl url = BASE_URL.resolve(path);
		return url != null && url.host().equals(BASE_URL.host()) ? url : null;
	}

	public static HttpUrl page(final String raw)
	{
		final HttpUrl url = raw == null ? null : HttpUrl.parse(raw);
		return url != null && url.isHttps() && url.host().equals(BASE_URL.host()) ? url : null;
	}

	public static Request.Builder request(final HttpUrl url)
	{
		return new Request.Builder().url(url).header("User-Agent", "Collective RuneLite Plugin");
	}

	public static void fetchImage(final OkHttpClient client, final HttpUrl url, final Consumer<BufferedImage> done)
	{
		client.newCall(request(url).get().build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(final Call call, final IOException e)
			{
				log.debug("Collective image request failed: {}", url.encodedPath(), e);
				done.accept(null);
			}

			@Override
			public void onResponse(final Call call, final Response response)
			{
				BufferedImage image = null;
				try (Response r = response)
				{
					if (r.isSuccessful() && r.body() != null)
					{
						image = ImageIO.read(r.body().byteStream());
					}
				}
				catch (IOException e)
				{
					log.debug("Collective image could not be read: {}", url.encodedPath(), e);
				}
				done.accept(image);
			}
		});
	}

	public static <T> void send(final OkHttpClient client, final Gson gson, final Request request, final Class<T> type,
		final Consumer<T> done)
	{
		send(client, gson, request, type, false, done);
	}

	public static <T> void send(final OkHttpClient client, final Gson gson, final Request request, final Class<T> type,
		final boolean readNotFound, final Consumer<T> done)
	{
		client.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(final Call call, final IOException e)
			{
				log.debug("Collective request failed: {}", request.url().encodedPath(), e);
				done.accept(null);
			}

			@Override
			public void onResponse(final Call call, final Response response)
			{
				T body = null;
				try (Response r = response)
				{
					if ((r.isSuccessful() || readNotFound && r.code() == 404) && r.body() != null)
					{
						body = gson.fromJson(r.body().charStream(), type);
					}
					else
					{
						log.debug("Collective request {} returned {}", request.url().encodedPath(), r.code());
					}
				}
				catch (JsonParseException | IllegalStateException e)
				{
					log.debug("Collective response could not be read: {}", request.url().encodedPath(), e);
				}
				done.accept(body);
			}
		});
	}
}

package cc.clancollective.plugin.ui;

